-- ============================================================================
-- PRODUCTION VARIANT: identical to revert_apartment_productid_to_unit_code.sql
-- except it omits SALES_OPPORTUNITY_PRODUCT, which does not exist in the
-- production schema (same schema-drift issue noted in the original rename
-- script's PROD variant). Dev already ran the full version successfully;
-- this is the prod run only.
-- ============================================================================

-- ============================================================================
-- Revert the 68 SAWA / Watan House apartment ProductIds from the A1-01-style
-- scheme (A-01..A-58, B166-01..B169-42) back to the original Unit Code values
-- from the source Excel sheets (Apt-001..Apt-508, B166-1..B169-408).
--
-- WHY
-- After applying fix_apartment_productid_naming_scheme.sql, the decision was
-- reversed: ProductId should be the Unit Code from the source sheet, not the
-- old-project A1-01 building/floor/seq scheme. This is the exact inverse of
-- that script (same FK-safe temp-table pattern, mapping reversed).
--
-- SCOPE: same 68 rows as before. ProductName reverts to the plain Unit Code
-- (e.g. 'Apt-001', 'B166-1') - no 'Apartment ' prefix. BUILDING_NUMBER for
-- SAWA reverts from 'A' back to 'Block A'; Watan House buildings (B166-B169)
-- were never changed so nothing to revert there.
--
-- WHAT REFERENCES THE CURRENT (A-xx/Bxxx-xx) IDS TODAY (both dev and prod,
-- swept across every FK column pointing at PRODUCT.PRODUCT_ID):
--   SALES_REQUEST: 2 rows - 10888 (A-12 -> Apt-102), 10889 (A-14 -> Apt-104).
--   Everything else: 0 rows, same as before. All FK columns are still
--   updated unconditionally as a safety net regardless.
--
-- PRE-FLIGHT: confirmed 0 collisions in dev for all 68 target IDs before
-- writing this script. Re-check if time has passed.
--
-- RUN ORDER: dev first, verify, then production (production also needs the
-- SALES_OPPORTUNITY_PRODUCT statement removed, same as the original script,
-- since that table doesn't exist there).
-- ============================================================================

START TRANSACTION;
SET FOREIGN_KEY_CHECKS = 0;

DROP TEMPORARY TABLE IF EXISTS PRODUCT_ID_REVERT_MAP;
CREATE TEMPORARY TABLE PRODUCT_ID_REVERT_MAP (
    CURRENT_ID    VARCHAR(60) PRIMARY KEY,
    TARGET_ID     VARCHAR(60) NOT NULL,
    TARGET_NAME   VARCHAR(255) NOT NULL,
    TARGET_BUILDING VARCHAR(60) NOT NULL
);

